const AppI18n=(()=>{
  const defaults={language:'tr',largeText:false,reducedMotion:false,autoSync:true};
  function normalize(value){return {language:['tr','en','de'].includes(value?.language)?value.language:'tr',largeText:value?.largeText===true,reducedMotion:value?.reducedMotion===true,autoSync:value?.autoSync!==false};}
  let settings;try{settings=normalize(JSON.parse(localStorage.getItem('seo-ui-settings')));}catch{settings={...defaults};}
  const normalizeApostrophe=value=>String(value).replace(/[‘’ʼ]/g,"'");
  const dictionary=new Map(UI_COPY.map(row=>[normalizeApostrophe(row[0]),row]));
  function t(value){const row=dictionary.get(normalizeApostrophe(value));return row?row[{tr:0,en:1,de:2}[settings.language]]:value;}
  function locale(){return {tr:'tr-TR',en:'en-US',de:'de-DE'}[settings.language];}
  function save(value){const next=normalize({...settings,...value});localStorage.setItem('seo-ui-settings',JSON.stringify(next));settings=next;return settings;}
  return {t,locale,save,normalize,defaults,get settings(){return settings;}};
})();
if(typeof module!=='undefined')module.exports={UI_COPY,AppI18n};
